  1	package com.pousada.service;
  2	
  3	import com.pousada.domain.Reservation;
  4	import com.pousada.domain.ReservationStatus;
  5	import com.pousada.domain.Room;
  6	import com.pousada.util.PriceCalculator;
  7	
  8	import java.math.BigDecimal;
  9	import java.time.LocalDate;
 10	import java.time.YearMonth;
 11	import java.util.*;
 12	
 13	public class ReportService {
 14	    private final ReservationRepository reservationRepo;
 15	    private final RoomRepository roomRepo;
 16	
 17	    public ReportService(ReservationRepository reservationRepo, RoomRepository roomRepo) {
 18	        this.reservationRepo = reservationRepo;
 19	        this.roomRepo = roomRepo;
 20	    }
 21	
 22	    public String generateOccupancyReport(LocalDate date) {
 23	        List<Reservation> occupiedReservations = new ArrayList<>();
 24	        for (Reservation r : reservationRepo.getAllReservations()) {
 25	            if (isPaidAndOccupiedOn(r, date)) {
 26	                occupiedReservations.add(r);
 27	            }
 28	        }
 29	        occupiedReservations.sort(Comparator.comparingInt(Reservation::getRoomNumber));
 30	
 31	        StringBuilder csv = new StringBuilder();
 32	        csv.append("Pousada Maré Alta,occupancy,").append(formatDateForReport(date)).append("\n");
 33	        csv.append("room,type,reservation,check_in,check_out\n");
 34	
 35	        for (Reservation r : occupiedReservations) {
 36	            Room room = roomRepo.getRoom(r.getRoomNumber());
 37	            csv.append(room.getNumber()).append(",")
 38	                    .append(room.getType().getDisplayName()).append(",")
 39	                    .append(r.getId()).append(",")
 40	                    .append(formatDateForReport(r.getCheckIn())).append(",")
 41	                    .append(formatDateForReport(r.getCheckOut())).append("\n");
 42	        }
 43	
 44	        csv.append("total,").append(occupiedReservations.size()).append("/").append(roomRepo.getAllRooms().size()).append("\n");
 45	
 46	        return csv.toString();
 47	    }
 48	
 49	    public String generateRevenueReport(YearMonth month) {
 50	        List<Reservation> monthReservations = new ArrayList<>();
 51	        for (Reservation r : reservationRepo.getAllReservations()) {
 52	            if (isPaidAndStartsInMonth(r, month)) {
 53	                monthReservations.add(r);
 54	            }
 55	        }
 56	        monthReservations.sort(Comparator.comparingInt((Reservation r) -> r.getCheckIn().getDayOfMonth())
 57	                .thenComparingLong(Reservation::getId));
 58	
 59	        StringBuilder csv = new StringBuilder();
 60	        csv.append("Pousada Maré Alta,revenue,").append(formatYearMonth(month)).append("\n");
 61	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 62	
 63	        BigDecimal total = BigDecimal.ZERO;
 64	        for (Reservation r : monthReservations) {
 65	            BigDecimal amount = calculateAmount(r);
 66	            csv.append(r.getId()).append(",")
 67	                    .append(r.getRoomNumber()).append(",")
 68	                    .append(formatDateForReport(r.getCheckIn())).append(",")
 69	                    .append(formatDateForReport(r.getCheckOut())).append(",")
 70	                    .append(r.getStatus()).append(",")
 71	                    .append(formatCurrencyForReport(amount)).append("\n");
 72	            total = total.add(amount);
 73	        }
 74	
 75	        csv.append("total,,,,").append(formatCurrencyForReport(total)).append("\n");
 76	
 77	        return csv.toString();
 78	    }
 79	
 80	    public String generateTourismTaxReport(YearMonth month) {
 81	        List<Reservation> monthReservations = new ArrayList<>();
 82	        for (Reservation r : reservationRepo.getAllReservations()) {
 83	            if (isPaidAndStartsInMonth(r, month)) {
 84	                monthReservations.add(r);
 85	            }
 86	        }
 87	        monthReservations.sort(Comparator.comparingInt((Reservation r) -> r.getCheckIn().getDayOfMonth())
 88	                .thenComparingLong(Reservation::getId));
 89	
 90	        StringBuilder csv = new StringBuilder();
 91	        csv.append("Pousada Maré Alta,tourism-tax,").append(formatYearMonth(month)).append("\n");
 92	        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
 93	
 94	        BigDecimal totalTax = BigDecimal.ZERO;
 95	        BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
 96	
 97	        for (Reservation r : monthReservations) {
 98	            BigDecimal tax = PriceCalculator.round(
 99	                    new BigDecimal(r.getGuests() * r.getNights()).multiply(TAX_PER_GUEST_PER_NIGHT)
100	            );
101	            csv.append(r.getId()).append(",")
102	                    .append(r.getRoomNumber()).append(",")
103	                    .append(formatDateForReport(r.getCheckIn())).append(",")
104	                    .append(formatDateForReport(r.getCheckOut())).append(",")
105	                    .append(r.getGuests()).append(",")
106	                    .append(r.getNights()).append(",")
107	                    .append(formatCurrencyForReport(tax)).append("\n");
108	            totalTax = totalTax.add(tax);
109	        }
110	
111	        csv.append("total,,,,,").append(formatCurrencyForReport(totalTax)).append("\n");
112	
113	        return csv.toString();
114	    }
115	
116	    public String generateRatePlansReport(YearMonth month) {
117	        Map<String, List<Reservation>> reservationsByPlan = new HashMap<>();
118	        reservationsByPlan.put("STANDARD", new ArrayList<>());
119	        reservationsByPlan.put("NON_REFUNDABLE", new ArrayList<>());
120	
121	        for (Reservation r : reservationRepo.getAllReservations()) {
122	            if (isPaidAndStartsInMonth(r, month)) {
123	                reservationsByPlan.get(r.getRatePlan().name()).add(r);
124	            }
125	        }
126	
127	        StringBuilder csv = new StringBuilder();
128	        csv.append("Pousada Maré Alta,rate-plans,").append(formatYearMonth(month)).append("\n");
129	        csv.append("rate_plan,reservations,amount\n");
130	
131	        BigDecimal totalAmount = BigDecimal.ZERO;
132	        int totalReservations = 0;
133	
134	        for (String planName : Arrays.asList("STANDARD", "NON_REFUNDABLE")) {
135	            List<Reservation> reservations = reservationsByPlan.get(planName);
136	            int count = reservations.size();
137	            BigDecimal amount = BigDecimal.ZERO;
138	
139	            for (Reservation r : reservations) {
140	                amount = amount.add(calculateAmount(r));
141	            }
142	
143	            csv.append(planName).append(",")
144	                    .append(count).append(",")
145	                    .append(formatCurrencyForReport(amount)).append("\n");
146	
147	            totalAmount = totalAmount.add(amount);
148	            totalReservations += count;
149	        }
150	
151	        csv.append("total,").append(totalReservations).append(",").append(formatCurrencyForReport(totalAmount)).append("\n");
152	
153	        return csv.toString();
154	    }
155	
156	    private boolean isPaidAndOccupiedOn(Reservation r, LocalDate date) {
157	        if (!isPaid(r)) return false;
158	        return !date.isBefore(r.getCheckIn()) && date.isBefore(r.getCheckOut());
159	    }
160	
161	    private boolean isPaidAndStartsInMonth(Reservation r, YearMonth month) {
162	        if (!isPaid(r)) return false;
163	        YearMonth checkInMonth = YearMonth.from(r.getCheckIn());
164	        return checkInMonth.equals(month);
165	    }
166	
167	    private boolean isPaid(Reservation r) {
168	        ReservationStatus status = r.getStatus();
169	        return status == ReservationStatus.CONFIRMED || status == ReservationStatus.CHECKED_IN || status == ReservationStatus.CHECKED_OUT;
170	    }
171	
172	    private BigDecimal calculateAmount(Reservation r) {
173	        BigDecimal paid = r.getAmountPaid();
174	        BigDecimal refunded = r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO;
175	        return paid.subtract(refunded);
176	    }
177	
178	    private String formatDateForReport(LocalDate date) {
179	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
180	    }
181	
182	    private String formatYearMonth(YearMonth month) {
183	        return String.format("%04d-%02d", month.getYear(), month.getMonthValue());
184	    }
185	
186	    private String formatCurrencyForReport(BigDecimal value) {
187	        return String.format("%.2f", value);
188	    }
189	}

