    1	package com.pousada.api;
    2	
    3	import com.google.gson.Gson;
    4	import com.google.gson.JsonObject;
    5	import com.pousada.domain.*;
    6	import com.pousada.service.*;
    7	import io.javalin.Javalin;
    8	import io.javalin.http.HttpStatus;
    9	
   10	import java.math.BigDecimal;
   11	import java.time.LocalDate;
   12	import java.time.YearMonth;
   13	import java.time.format.DateTimeFormatter;
   14	import java.time.format.DateTimeParseException;
   15	import java.util.LinkedHashMap;
   16	import java.util.Map;
   17	
   18	public class ApiController {
   19	    private final ReservationService reservationService;
   20	    private final ReportService reportService;
   21	    private final RoomRepository roomRepo;
   22	    private final MessageRepository messageRepo;
   23	    private final ReservationRepository reservationRepo;
   24	    private final Gson gson;
   25	
   26	    public ApiController(ReservationService reservationService, ReportService reportService,
   27	                        RoomRepository roomRepo, MessageRepository messageRepo, ReservationRepository reservationRepo) {
   28	        this.reservationService = reservationService;
   29	        this.reportService = reportService;
   30	        this.roomRepo = roomRepo;
   31	        this.messageRepo = messageRepo;
   32	        this.reservationRepo = reservationRepo;
   33	        this.gson = new Gson();
   34	    }
   35	
   36	    public void setupRoutes(Javalin app) {
   37	        app.get("/rooms", ctx -> {
   38	            var rooms = roomRepo.getAllRooms();
   39	            var roomList = rooms.stream().map(room -> {
   40	                Map<String, Object> data = new LinkedHashMap<>();
   41	                data.put("number", room.getNumber());
   42	                data.put("type", room.getType().getDisplayName());
   43	                data.put("capacity", room.getCapacity());
   44	                data.put("nightlyRate", room.getNightlyRate().doubleValue());
   45	                return data;
   46	            }).toList();
   47	            ctx.json(roomList);
   48	        });
   49	
   50	        app.post("/reservations", ctx -> {
   51	            try {
   52	                var body = gson.fromJson(ctx.body(), JsonObject.class);
   53	
   54	                if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
   55	                    !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
   56	                    !body.has("guests") || !body.has("ratePlan")) {
   57	                    ctx.status(400).json(error("INVALID_REQUEST", "Missing required fields"));
   58	                    return;
   59	                }
   60	
   61	                int roomNumber = body.get("roomNumber").getAsInt();
   62	                String guestName = body.get("guestName").getAsString();
   63	                String guestEmail = body.get("guestEmail").getAsString();
   64	                String guestCpf = body.get("guestCpf").getAsString();
   65	                String checkInStr = body.get("checkIn").getAsString();
   66	                String checkOutStr = body.get("checkOut").getAsString();
   67	                int guests = body.get("guests").getAsInt();
   68	                String ratePlanStr = body.get("ratePlan").getAsString();
   69	
   70	                LocalDate checkIn;
   71	                LocalDate checkOut;
   72	                try {
   73	                    checkIn = LocalDate.parse(checkInStr, DateTimeFormatter.ISO_LOCAL_DATE);
   74	                    checkOut = LocalDate.parse(checkOutStr, DateTimeFormatter.ISO_LOCAL_DATE);
   75	                } catch (DateTimeParseException e) {
   76	                    ctx.status(400).json(error("INVALID_REQUEST", "Invalid date format"));
   77	                    return;
   78	                }
   79	
   80	                if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
   81	                    ctx.status(400).json(error("INVALID_REQUEST", "Checkout must be after checkin"));
   82	                    return;
   83	                }
   84	
   85	                if (guests < 1) {
   86	                    ctx.status(400).json(error("INVALID_REQUEST", "At least one guest required"));
   87	                    return;
   88	                }
   89	
   90	                Room room = roomRepo.getRoom(roomNumber);
   91	                if (room == null) {
   92	                    ctx.status(404).json(error("ROOM_NOT_FOUND", "Room not found"));
   93	                    return;
   94	                }
   95	
   96	                if (guests > room.getCapacity()) {
   97	                    ctx.status(422).json(error("CAPACITY_EXCEEDED", "Too many guests for this room"));
   98	                    return;
   99	                }
  100	
  101	                RatePlan ratePlan;
  102	                try {
  103	                    ratePlan = RatePlan.valueOf(ratePlanStr);
  104	                } catch (IllegalArgumentException e) {
  105	                    ctx.status(400).json(error("INVALID_REQUEST", "Invalid rate plan"));
  106	                    return;
  107	                }
  108	
  109	                if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
  110	                    ctx.status(409).json(error("ROOM_UNAVAILABLE", "Room not available for these dates"));
  111	                    return;
  112	                }
  113	
  114	                try {
  115	                    Reservation reservation = reservationService.createReservation(roomNumber, guestName, guestEmail,
  116	                            guestCpf, checkIn, checkOut, guests, ratePlan);
  117	
  118	                    ctx.status(201).json(reservationToJson(reservation));
  119	                } catch (IllegalArgumentException e) {
  120	                    ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
  121	                }
  122	            } catch (Exception e) {
  123	                e.printStackTrace();
  124	                ctx.status(400).json(error("INVALID_REQUEST", "Invalid request body"));
  125	            }
  126	        });
  127	
  128	        app.get("/reservations/{id}", ctx -> {
  129	            try {
  130	                long id = Long.parseLong(ctx.pathParam("id"));
  131	                Reservation reservation = reservationService.getReservation(id);
  132	
  133	                if (reservation == null) {
  134	                    ctx.status(404).json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
  135	                    return;
  136	                }
  137	
  138	                ctx.json(reservationToJson(reservation));
  139	            } catch (NumberFormatException e) {
  140	                ctx.status(400).json(error("INVALID_REQUEST", "Invalid reservation id"));
  141	            }
  142	        });
  143	
  144	        app.post("/reservations/{id}/confirmation", ctx -> {
  145	            try {
  146	                long id = Long.parseLong(ctx.pathParam("id"));
  147	                Reservation reservation = reservationService.getReservation(id);
  148	
  149	                if (reservation == null) {
  150	                    ctx.status(404).json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
  151	                    return;
  152	                }
  153	
  154	                if (reservation.getStatus() != ReservationStatus.PENDING) {
  155	                    ctx.status(409).json(error("OPERATION_NOT_ALLOWED", "Reservation cannot be confirmed"));
  156	                    return;
  157	                }
  158	
  159	                Reservation confirmed = reservationService.confirmReservation(id, reservation.getTotal());
  160	                ctx.json(reservationToJson(confirmed));
  161	            } catch (NumberFormatException e) {
  162	                ctx.status(400).json(error("INVALID_REQUEST", "Invalid reservation id"));
  163	            }
  164	        });
  165	
  166	        app.post("/reservations/{id}/cancellation", ctx -> {
  167	            try {
  168	                long id = Long.parseLong(ctx.pathParam("id"));
  169	                Reservation reservation = reservationService.getReservation(id);
  170	
  171	                if (reservation == null) {
  172	                    ctx.status(404).json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
  173	                    return;
  174	                }
  175	
