  431	package com.pousada.util;
  432	
  433	import java.math.BigDecimal;
  434	import java.math.RoundingMode;
  435	import java.time.LocalDate;
  436	
  437	public class PriceCalculator {
  438	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
  439	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
  440	
  441	    public static boolean isHighSeason(LocalDate date) {
  442	        int month = date.getMonthValue();
  443	        int day = date.getDayOfMonth();
  444	
  445	        if (month == 7) return true;
  446	        if (month == 12 && day >= 15) return true;
  447	        if (month >= 1 && month <= 2) return true;
  448	
  449	        return false;
  450	    }
  451	
  452	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
  453	        if (isHighSeason(date)) {
  454	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
  455	        }
  456	        return baseRate;
  457	    }
  458	
  459	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
  460	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
  461	    }
  462	
  463	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
  464	        BigDecimal subtotal = BigDecimal.ZERO;
  465	        LocalDate current = checkIn;
  466	
  467	        while (current.isBefore(checkOut)) {
  468	            subtotal = subtotal.add(calculateNightlyRate(baseRate, current));
  469	            current = current.plusDays(1);
  470	        }
  471	
  472	        return round(subtotal);
  473	    }
  474	
  475	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
  476	        if ("NON_REFUNDABLE".equals(ratePlan)) {
  477	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
  478	        }
  479	        return round(BigDecimal.ZERO);
  480	    }
  481	
  482	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
  483	        return round(subtotal.subtract(discount));
  484	    }
  485	
  486	    public static BigDecimal round(BigDecimal value) {
  487	        return value.setScale(2, RoundingMode.HALF_EVEN);
  488	    }
  489	}
