  340	            LocalDate rCheckOut = r.getCheckOut();
  341	
  342	            if (!(checkOut.isEqual(rCheckIn) || checkOut.isBefore(rCheckIn)) &&
  343	                !(checkIn.isEqual(rCheckOut) || checkIn.isAfter(rCheckOut))) {
