    20	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    21	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    22	        Room room = roomRepo.getRoom(roomNumber);
    23	        if (room == null) {
    24	            return null;
    25	        }
    26	
    27	        if (guests < 1 || guests > room.getCapacity()) {
    28	            throw new IllegalArgumentException("Guest count exceeds room capacity");
    29	        }
    30	
    31	        int nights = PriceCalculator.calculateNights(checkIn, checkOut);
    32	        if (nights <= 0) {
    33	            throw new IllegalArgumentException("Checkout must be after checkin");
    34	        }
    35	
    36	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    37	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan.name());
    38	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    39	
    40	        long id = reservationRepo.getNextId();
    41	        Reservation reservation = new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
    42	                checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
    43	
    44	        return reservationRepo.save(reservation);
    45	    }
