   125	    public String generateReceipt(Reservation reservation) {
   126	        Room room = roomRepo.getRoom(reservation.getRoomNumber());
   127	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
   128	
   129	        String receipt = "Comprovante de reserva nº " + reservation.getId() + "\n" +
