   131	                "Quarto: " + room.getNumber() + " (" + room.getType().getDisplayName() + ")\n" +
   132	                "Entrada: " + formatDate(reservation.getCheckIn()) + " | Saída: " + formatDate(reservation.getCheckOut()) + " | " + nightsText + "\n" +
   133	                "Diárias: " + formatCurrency(reservation.getSubtotal());
   134	
   135	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
