     3	import com.pousada.domain.*;
     4	import com.pousada.util.PriceCalculator;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	
     9	public class ReservationService {
    10	    private final ReservationRepository reservationRepo;
    11	    private final RoomRepository roomRepo;
    12	    private final MessageRepository messageRepo;
    13	
    14	    public ReservationService(ReservationRepository reservationRepo, RoomRepository roomRepo, MessageRepository messageRepo) {
    15	        this.reservationRepo = reservationRepo;
    16	        this.roomRepo = roomRepo;
    17	        this.messageRepo = messageRepo;
    18	    }
    19	
    20	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    21	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    22	        Room room = roomRepo.getRoom(roomNumber);
    23	        if (room == null) {
    24	            return null;
    25	        }
    26	
    27	        if (guests < 1 || guests > room.getCapacity()) {
    28	            throw new IllegalArgumentException("Guest count exceeds room capacity");
    29	        }
    30	
    31	        int nights = PriceCalculator.calculateNights(checkIn, checkOut);
    32	        if (nights <= 0) {
    33	            throw new IllegalArgumentException("Checkout must be after checkin");
    34	        }
    35	
    36	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    37	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan.name());
    38	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
    39	
    40	        long id = reservationRepo.getNextId();
    41	        Reservation reservation = new Reservation(id, roomNumber, guestName, guestEmail, guestCpf,
    42	                checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
    43	
    44	        return reservationRepo.save(reservation);
    45	    }
    46	
    47	    public Reservation getReservation(long id) {
    48	        return reservationRepo.getReservation(id);
    49	    }
    50	
    51	    public Reservation confirmReservation(long id, BigDecimal amount) {
    52	        Reservation reservation = reservationRepo.getReservation(id);
    53	        if (reservation == null || reservation.getStatus() != ReservationStatus.PENDING) {
    54	            return null;
    55	        }
    56	
    57	        reservation.confirm(amount);
    58	
    59	        String body = generateConfirmationEmail(reservation);
    60	        Message message = new Message(messageRepo.getNextId(), "EMAIL", reservation.getGuestEmail(),
    61	                "Reserva confirmada - Pousada Maré Alta", body);
    62	        messageRepo.save(message);
    63	
    64	        return reservation;
    65	    }
    66	
    67	    public Reservation cancelReservation(long id) {
    68	        Reservation reservation = reservationRepo.getReservation(id);
    69	        if (reservation == null) {
    70	            return null;
    71	        }
    72	
    73	        ReservationStatus status = reservation.getStatus();
    74	        if (status == ReservationStatus.CHECKED_IN || status == ReservationStatus.CHECKED_OUT || status == ReservationStatus.CANCELLED) {
    75	            return null;
    76	        }
    77	
    78	        BigDecimal refundAmount = calculateRefund(reservation);
    79	        reservation.cancel(refundAmount);
    80	
    81	        return reservation;
    82	    }
    83	
    84	    public Reservation checkIn(long id) {
    85	        Reservation reservation = reservationRepo.getReservation(id);
    86	        if (reservation == null || reservation.getStatus() != ReservationStatus.CONFIRMED) {
    87	            return null;
    88	        }
    89	
    90	        reservation.checkIn();
    91	        return reservation;
    92	    }
    93	
    94	    public Reservation checkOut(long id) {
    95	        Reservation reservation = reservationRepo.getReservation(id);
    96	        if (reservation == null || reservation.getStatus() != ReservationStatus.CHECKED_IN) {
    97	            return null;
    98	        }
    99	
   100	        reservation.checkOut();
   101	        return reservation;
   102	    }
   103	
   104	    private BigDecimal calculateRefund(Reservation reservation) {
   105	        if (reservation.getStatus() == ReservationStatus.PENDING) {
   106	            return PriceCalculator.round(BigDecimal.ZERO);
   107	        }
   108	
   109	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
   110	            return PriceCalculator.round(BigDecimal.ZERO);
   111	        }
   112	
   113	        return reservation.getAmountPaid();
   114	    }
   115	
   116	    private String generateConfirmationEmail(Reservation reservation) {
   117	        String receipt = generateReceipt(reservation);
   118	        return "Olá, " + reservation.getGuestName() + "!\n\n" +
   119	               "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
   120	               receipt + "\n" +
   121	               "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
   122	               "Até breve!";
   123	    }
   124	
   125	    public String generateReceipt(Reservation reservation) {
   126	        Room room = roomRepo.getRoom(reservation.getRoomNumber());
   127	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
   128	
   129	        String receipt = "Comprovante de reserva nº " + reservation.getId() + "\n" +
   130	                "Hóspede: " + reservation.getGuestName() + " (CPF " + reservation.getGuestCpf() + ")\n" +
   131	                "Quarto: " + room.getNumber() + " (" + room.getType().getDisplayName() + ")\n" +
   132	                "Entrada: " + formatDate(reservation.getCheckIn()) + " | Saída: " + formatDate(reservation.getCheckOut()) + " | " + nightsText + "\n" +
   133	                "Diárias: " + formatCurrency(reservation.getSubtotal());
   134	
   135	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   136	            receipt += "\nDesconto: " + formatCurrency(reservation.getDiscount());
   137	        }
   138	
   139	        receipt += "\nTotal: " + formatCurrency(reservation.getTotal());
   140	
   141	        return receipt;
   142	    }
   143	
   144	    private String formatDate(LocalDate date) {
   145	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
   146	    }
   147	
   148	    private String formatCurrency(BigDecimal value) {
   149	        return "R$ " + String.format("%.2f", value).replace(".", ",");
   150	    }
   151	}
